/**
 * Notion - Page Resource - Zod Schema Factory
 * Exports a factory that unions all operation schemas for this resource.
 *
 * Schema helpers (z, expressionSchema, etc.) are passed as parameters
 * by the schema-validator, not imported from external files.
 *
 * @generated - CommonJS JavaScript for runtime loading
 */

const getArchiveSchema = require('./operation_archive.schema');
const getCreateSchema = require('./operation_create.schema');
const getGetMarkdownSchema = require('./operation_get_markdown.schema');
const getSearchSchema = require('./operation_search.schema');
const getUpdateMarkdownSchema = require('./operation_update_markdown.schema');

module.exports = function getSchema(helpers) {
  const { parameters, z } = helpers;
  // Apply operation default if not set
  const effectiveParams = parameters.operation === undefined ? { ...parameters, operation: 'append' } : parameters;
  return z.union([
    getArchiveSchema({ ...helpers, parameters: effectiveParams }),
    getCreateSchema({ ...helpers, parameters: effectiveParams }),
    getGetMarkdownSchema({ ...helpers, parameters: effectiveParams }),
    getSearchSchema({ ...helpers, parameters: effectiveParams }),
    getUpdateMarkdownSchema({ ...helpers, parameters: effectiveParams }),
  ]);
};